def mark_plans(apps, schema_editor):
    """The seeded commercial plans are unapproved examples: DRAFT, not offered
    to anyone. Legacy is SYSTEM (kept for firms that predate subscriptions).
    No firm's subscription is changed. Adds the new ai.summaries.month key
    (counted, no limit) to the draft and system plans."""
    from subscriptions import catalogue as C
    Plan = apps.get_model('subscriptions', 'Plan')
    PlanEntitlement = apps.get_model('subscriptions', 'PlanEntitlement')
    for plan in Plan.objects.all():
        plan.family = plan.family or plan.code
        plan.state = 'SYSTEM' if plan.code == C.LEGACY else 'DRAFT'
        plan.is_public = False
        plan.save(update_fields=['family', 'state', 'is_public'])
    C.ensure_plans(Plan=Plan, PlanEntitlement=PlanEntitlement)


